CREATE TABLE IF NOT EXISTS richo_runtime_quotas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quota_key text NOT NULL UNIQUE,max_in_flight integer NOT NULL DEFAULT 8,max_queue_depth integer NOT NULL DEFAULT 1000,budget_ms integer NOT NULL DEFAULT 120000,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_runtime_workers(id text PRIMARY KEY,capabilities jsonb NOT NULL DEFAULT '[]'::jsonb,max_concurrency integer NOT NULL DEFAULT 1,in_flight integer NOT NULL DEFAULT 0,capacity_score numeric(10,4) NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'healthy',last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_runtime_dead_letters(id uuid PRIMARY KEY,job_id uuid,operation text,payload_hash text NOT NULL,error jsonb NOT NULL,replay_count integer NOT NULL DEFAULT 0,max_replays integer NOT NULL DEFAULT 3,created_at timestamptz NOT NULL DEFAULT now(),last_replayed_at timestamptz);
CREATE TABLE IF NOT EXISTS richo_runtime_metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid,metric text NOT NULL,value numeric(20,6) NOT NULL,status text,observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_runtime_fences(job_id uuid PRIMARY KEY,worker_id text NOT NULL,fence text NOT NULL UNIQUE,lease_expires_at timestamptz NOT NULL,claimed_at timestamptz NOT NULL DEFAULT now());
